-- =====================================================================
-- Nuove carte: 85 carte (5 fazioni x 17 righe della tabella) al posto di tutto il catalogo attuale.
-- Eseguire nello SQL editor di Supabase, UN BLOCCO ALLA VOLTA, nell'ordine (1, 2, 3, 4).
-- Clownerie (giallo) non ha ancora carte: finché non le aggiungiamo non viene scelta nei mazzi.
-- =====================================================================

-- 1) ANTEPRIMA (non modifica niente): cosa verrà cancellato.
select f.code as fazione, c.card_type, count(*) as carte
from public.cards c left join public.factions f on f.id = c.faction_id
group by 1, 2 order by 1, 2;

-- 2) COPIA DI SICUREZZA. Le tabelle nuove in "public" sono leggibili dal browser di default:
--    la riga "enable row level security" senza policy le chiude a tutti tranne che a te nel pannello.
create table public.cards_backup_20261006 as table public.cards;
alter table public.cards_backup_20261006 enable row level security;
create table public.card_subtype_links_backup_20261006 as table public.card_subtype_links;
alter table public.card_subtype_links_backup_20261006 enable row level security;

-- 3) CANCELLAZIONE DELLE CARTE VECCHIE (tutte, Mostrissimi e boss compresi) E INSERIMENTO DELLE NUOVE.
--    Un unico blocco: se qualcosa va storto non cambia niente. Le tabelle che puntano alle carte
--    (collegamenti ai sottotipi, ecc.) vengono svuotate dalle sole righe collegate, trovate in automatico.
do $$
declare r record;
begin
  for r in
    select c.conrelid::regclass as child, a.attname as col
    from pg_constraint c
    join pg_attribute a on a.attrelid = c.conrelid and a.attnum = c.conkey[1]
    where c.contype = 'f' and c.confrelid = 'public.cards'::regclass and c.conrelid <> 'public.cards'::regclass
  loop
    execute format('delete from %s where %I in (select id from public.cards)', r.child, r.col);
  end loop;
  delete from public.cards;

  insert into public.cards
    (id, name, faction_id, card_type, mana_cost, attack, hp, effect_text, effect_json, effect_on_death_json,
