-- 4) VERIFICA: devono risultare 17 carte per ognuna delle 5 fazioni (85 in tutto).
select f.code as fazione, count(*) as carte,
       count(*) filter (where c.card_type = 'maledizione') as maledizioni,
       count(*) filter (where c.card_type = 'monster') as mostri,
       count(*) filter (where c.card_type = 'instant') as trappole,
       count(*) filter (where c.card_type = 'aura') as aure,
       count(*) filter (where c.card_type = 'terraforma') as terraforme
from public.cards c join public.factions f on f.id = c.faction_id
group by 1 order by 1;

